(function () {
  var KB = {"faqs": [{"id": "siete-un-team-proveniente-da-google-cracovia", "q": "Siete un team proveniente da Google Cracovia?", "a": "Sì. Easy Tag è lo spin-off del team italiano che ha lavorato sui tag a Cracovia. Il percorso è raccontato in Chi siamo .", "href": "/faq#siete-un-team-proveniente-da-google-cracovia"}, {"id": "cosa-ricevo-dopo-l-acquisto", "q": "Cosa ricevo dopo l'acquisto?", "a": "Il file JSON del container Google Tag Manager e le istruzioni, via email. I container pronti sono nello Shop .", "href": "/faq#cosa-ricevo-dopo-l-acquisto"}, {"id": "i-prezzi-includono-l-iva", "q": "I prezzi includono l'IVA?", "a": "Sì. Tutti i prezzi indicati sono IVA inclusa.", "href": "/faq#i-prezzi-includono-l-iva"}, {"id": "perche-alcuni-prodotti-sono-su-preventivo", "q": "Perché alcuni prodotti sono su preventivo?", "a": "E-commerce, Dynamic Remarketing e Consent Mode dipendono da CMS e data layer. Le schede sono Tracker E-commerce , Dynamic Remarketing e Consent Mode v2 .", "href": "/faq#perche-alcuni-prodotti-sono-su-preventivo"}, {"id": "cos-e-esattamente-il-datalayer-nella-tag-platform-di-google", "q": "Cos'è esattamente il dataLayer nella Tag Platform di Google?", "a": "Il dataLayer è un array JavaScript globale, di default window.dataLayer , che passa variabili ed eventi dalla pagina a Google Tag Manager e a gtag.js . Non si leggono prezzi, id o stati del form dal DOM. I container come il Tracker E-commerce e il Dynamic Remarketing dipendono da questo livello.", "href": "/faq#cos-e-esattamente-il-datalayer-nella-tag-platform-di-google"}, {"id": "perche-il-datalayer-si-inizializza-con-window-datalayer-window-datalayer", "q": "Perché il dataLayer si inizializza con window.dataLayer = window.dataLayer || [] prima dello snippet?", "a": "Per creare l'array solo se non esiste, senza cancellare push già presenti. GTM e gtag.js trovano così un'istanza valida all'avvio. Lo snippet di Google Tag Manager va caricato dopo questa riga, come descritto nella sezione di installazione di questa guida.", "href": "/faq#perche-il-datalayer-si-inizializza-con-window-datalayer-window-datalayer"}, {"id": "cosa-succede-se-si-sovrascrive-window-datalayer-o-window-datalayer-dopo-", "q": "Cosa succede se si sovrascrive window.dataLayer = [] o window.dataLayer = {} dopo il caricamento?", "a": "Si rompe il riferimento su cui GTM e gtag.js hanno agganciato listener e coda interna. Gli eventi già in coda si perdono. I tag non partono o partono con dati incoerenti. Non usare un oggetto {} : il dataLayer è un array, non una mappa.", "href": "/faq#cosa-succede-se-si-sovrascrive-window-datalayer-o-window-datalayer-dopo-"}, {"id": "come-elabora-i-messaggi-il-datalayer", "q": "Come elabora i messaggi il dataLayer?", "a": "Con una coda FIFO (First-In, First-Out): i push si leggono uno alla volta, nell'ordine di arrivo. Se il messaggio contiene event , Google Tag Manager valuta i trigger e attiva i tag collegati prima di passare al messaggio successivo.", "href": "/faq#come-elabora-i-messaggi-il-datalayer"}, {"id": "cosa-significa-che-un-datalayer-push-da-uno-script-esterno-o-da-un-custo", "q": "Cosa significa che un dataLayer.push() da uno script esterno o da un Custom HTML viene accodato?", "a": "L'esecuzione è asincrona rispetto agli eventi già in coda. Una variabile scritta senza event può non essere ancora visibile quando scatta l'evento successivo. Per sincronizzare, invia sempre una chiave event dedicata e usa un attivatore Evento personalizzato.", "href": "/faq#cosa-significa-che-un-datalayer-push-da-uno-script-esterno-o-da-un-custo"}, {"id": "perche-e-sconsigliato-mettere-gtag-js-dentro-un-tag-html-personalizzato-", "q": "Perché è sconsigliato mettere gtag.js dentro un tag HTML personalizzato in GTM?", "a": "Perché duplica il ciclo di vita del tag, può confliggere sulla coda e su gtag() , e salta i controlli nativi di GTM, consenso incluso. Usa i modelli di tag nativi per Google Ads , Google Analytics 4 e Floodlight.", "href": "/faq#perche-e-sconsigliato-mettere-gtag-js-dentro-un-tag-html-personalizzato-"}, {"id": "come-si-inviano-un-evento-e-piu-variabili-in-un-solo-push", "q": "Come si inviano un evento e più variabili in un solo push?", "a": "Con un unico oggetto: dataLayer.push({event: 'customize', color: 'red', conversionValue: 50}) . Tutte le chiavi entrano nello stato del dataLayer e sono leggibili dai tag attivati da quell'evento. Non spezzare valore e nome evento in due push diversi.", "href": "/faq#come-si-inviano-un-evento-e-piu-variabili-in-un-solo-push"}, {"id": "cosa-accade-se-si-esegue-il-push-di-una-variabile-con-lo-stesso-nome-di-", "q": "Cosa accade se si esegue il push di una variabile con lo stesso nome di una chiave già esistente?", "a": "Il nuovo valore sovrascrive il precedente nello stato corrente, da quel punto della coda in avanti. I messaggi già elaborati non vengono riscritti.", "href": "/faq#cosa-accade-se-si-esegue-il-push-di-una-variabile-con-lo-stesso-nome-di-"}, {"id": "quanto-restano-attive-le-variabili-inserite-nel-datalayer", "q": "Quanto restano attive le variabili inserite nel dataLayer?", "a": "Restano disponibili per tutta la permanenza su quella pagina, finché non le sovrascrivi o non resetti lo stato. Su più pagine vanno ripubblicate a ogni caricamento, con lo stesso nome: visitorType in una pagina e visitor_type in un'altra sono due chiavi diverse.", "href": "/faq#quanto-restano-attive-le-variabili-inserite-nel-datalayer"}, {"id": "qual-e-la-differenza-tra-datalayer-push-function-e-gtag", "q": "Qual è la differenza tra dataLayer.push(function) e gtag(...)?", "a": "Se passi una funzione a dataLayer.push(function(){ ... }) , this punta al modello dati astratto di GTM ( this.set , this.get , this.reset ). gtag(function(){ ... }) non è un comando valido: la funzione viene ignorata.", "href": "/faq#qual-e-la-differenza-tra-datalayer-push-function-e-gtag"}, {"id": "a-cosa-serve-this-reset-dentro-una-funzione-passata-a-datalayer-push", "q": "A cosa serve this.reset() dentro una funzione passata a dataLayer.push()?", "a": "Ripulisce lo stato accumulato nel modello dati. Serve sulle pagine che restano aperte a lungo e nelle Single Page Application, per non trascinare valori della vista precedente. Il pageview delle SPA va poi rinviato come descritto nella guida Google Analytics 4 .", "href": "/faq#a-cosa-serve-this-reset-dentro-una-funzione-passata-a-datalayer-push"}, {"id": "come-si-usano-this-set-e-this-get-nei-metodi-personalizzati-del-datalaye", "q": "Come si usano this.set() e this.get() nei metodi personalizzati del dataLayer?", "a": "Leggono e scrivono coppie chiave-valore sul modello dati astratto, in modo controllato. Esempio: this.set('time', new Date()) e, in un passo successivo, this.get('time') . Non sostituiscono un dataLayer.push con event quando devi attivare un tag.", "href": "/faq#come-si-usano-this-set-e-this-get-nei-metodi-personalizzati-del-datalaye"}, {"id": "si-puo-rinominare-datalayer", "q": "Si può rinominare dataLayer?", "a": "Sì. Cambia il nome dell'array nello snippet, passa l=myNewName nell'URL dello script GTM e allinea ogni chiamata a window.myNewName.push(...) . Se una sola integrazione continua a scrivere su dataLayer , gli eventi si dividono su due code.", "href": "/faq#si-puo-rinominare-datalayer"}, {"id": "quali-sono-gli-errori-sintattici-piu-frequenti-su-datalayer-push", "q": "Quali sono gli errori sintattici più frequenti su dataLayer.push()?", "a": "datalayer.push al posto di dataLayer.push (la L è maiuscola). Chiavi con caratteri speciali, come new-variable , scritte senza virgolette. JSON malformato: virgola finale, apici singoli dove il parser si aspetta JSON stretto, parentesi non chiuse.", "href": "/faq#quali-sono-gli-errori-sintattici-piu-frequenti-su-datalayer-push"}, {"id": "come-si-verifica-in-tempo-reale-lo-stato-del-datalayer", "q": "Come si verifica in tempo reale lo stato del dataLayer?", "a": "Con Google Tag Assistant su tagassistant.google.com, oppure con la modalità Anteprima di Google Tag Manager. Per ogni evento in sequenza vedi i valori del dataLayer e lo stato del consenso. Il consenso si approfondisce nella guida Consent Mode .", "href": "/faq#come-si-verifica-in-tempo-reale-lo-stato-del-datalayer"}, {"id": "cos-e-il-tag-google-gtag-js-e-come-si-collega-a-piu-destinazioni", "q": "Cos'è il Tag Google (gtag.js) e come si collega a più destinazioni?", "a": "È un solo framework JavaScript che raccoglie i dati e li instrada verso più destinazioni: Google Ads, Google Analytics, Floodlight e altre, tramite un TAG_ID o configurazioni collegate. In un contenitore GTM lo stesso ruolo lo fanno i tag nativi, non una seconda copia di gtag incollata in pagina.", "href": "/faq#cos-e-il-tag-google-gtag-js-e-come-si-collega-a-piu-destinazioni"}, {"id": "qual-e-il-ruolo-del-prefisso-dell-id-gtm-g-aw-nell-url-dello-script", "q": "Qual è il ruolo del prefisso dell'ID (GTM-, G-, AW-) nell'URL dello script?", "a": "Dice al loader che tipo di contenitore sta avviando e quali permessi applicare. GTM- è un contenitore Google Tag Manager. G- è una proprietà Google Analytics 4. AW- è un account Google Ads.", "href": "/faq#qual-e-il-ruolo-del-prefisso-dell-id-gtm-g-aw-nell-url-dello-script"}, {"id": "perche-gtag-config-e-indicato-come-deprecato-negli-snippet-piu-recenti", "q": "Perché gtag('config', ...) è indicato come deprecato negli snippet più recenti?", "a": "Google sposta la configurazione delle destinazioni nell'interfaccia di Google Tag Manager e, in pagina, verso gtag('set', ...) . gtag('config') già pubblicato resta retrocompatibile: non va rimosso a metà migrazione senza un piano di misura.", "href": "/faq#perche-gtag-config-e-indicato-come-deprecato-negli-snippet-piu-recenti"}, {"id": "come-funziona-il-raggruppamento-e-l-instradamento-in-gtag-js", "q": "Come funziona il raggruppamento e l'instradamento in gtag.js?", "a": "Puoi centralizzare i parametri comuni e mandare un evento solo ad alcune destinazioni, per esempio un Measurement ID G- oppure un account AW- , invece di inviare tutto ovunque. È lo stesso principio del parametro send_to spiegato nella guida Tag nativo Google Ads .", "href": "/faq#come-funziona-il-raggruppamento-e-l-instradamento-in-gtag-js"}, {"id": "come-si-verifica-nella-scheda-rete-che-il-tag-stia-trasmettendo", "q": "Come si verifica nella scheda Rete che il tag stia trasmettendo?", "a": "Filtra le richieste per dominio. googletagmanager.com carica il contenitore. google-analytics.com o analytics.google.com portano gli hit GA4. googleadservices.com e i domini pubblicitari Google portano Ads. doubleclick.net compare con Floodlight.", "href": "/faq#come-si-verifica-nella-scheda-rete-che-il-tag-stia-trasmettendo"}, {"id": "come-cambia-il-debug-con-il-tagging-lato-server", "q": "Come cambia il debug con il tagging lato server?", "a": "Nel browser vedi le richieste verso il tuo endpoint di tagging, di solito un sottodominio di prima parte. I colpi verso i server finali di Google Ads e Google Analytics partono dal server container, non dal browser dell'utente.", "href": "/faq#come-cambia-il-debug-con-il-tagging-lato-server"}, {"id": "cos-e-il-gateway-del-tag-google-per-gli-inserzionisti", "q": "Cos'è il gateway del tag Google per gli inserzionisti?", "a": "È una configurazione che fa passare le richieste del tag da un percorso di prima parte controllato da te. Serve a rendere la misura più continua quando il browser limita gli script di terze parti, sempre nel rispetto del Consent Mode .", "href": "/faq#cos-e-il-gateway-del-tag-google-per-gli-inserzionisti"}, {"id": "come-si-gestisce-il-tagging-sulle-pagine-amp-rispetto-al-web-standard", "q": "Come si gestisce il tagging sulle pagine AMP rispetto al web standard?", "a": "AMP ha componenti nativi per i tag e per GTM, con limiti propri. GTM per AMP non copre Google Analytics come il web: servono snippet AMP dedicati e va controllato il passaggio di cid e gclid verso le pagine non AMP.", "href": "/faq#come-si-gestisce-il-tagging-sulle-pagine-amp-rispetto-al-web-standard"}, {"id": "come-si-filtra-il-traffico-di-integrazioni-cms-per-esempio-shopify-in-go", "q": "Come si filtra il traffico di integrazioni CMS, per esempio Shopify, in Google Analytics?", "a": "Con filtri dei dati o esclusioni dedicate, così gli eventi automatici del CMS e il traffico interno non gonfiano sessioni e conversioni. Il funnel che vuoi leggere in report è quello del Tracker E-commerce , non quello di prova del tema.", "href": "/faq#come-si-filtra-il-traffico-di-integrazioni-cms-per-esempio-shopify-in-go"}, {"id": "perche-usare-un-solo-datalayer-per-pagina-anche-con-piu-tag", "q": "Perché usare un solo dataLayer per pagina anche con più tag?", "a": "Un solo array tiene un ordine temporale unico. Due code separate fanno leggere a un tag valori assenti o vecchi. Vale anche quando in pagina convivono GA4, Google Ads e il tag di Consent Mode v2 .", "href": "/faq#perche-usare-un-solo-datalayer-per-pagina-anche-con-piu-tag"}, {"id": "qual-e-la-differenza-tra-eventi-automatici-misurazione-avanzata-eventi-c", "q": "Qual è la differenza tra eventi automatici, misurazione avanzata, eventi consigliati ed eventi personalizzati?", "a": "Sono quattro livelli, dal più generico al più tuo. Automatici: partono senza configurazione extra. Misurazione avanzata: scroll, clic in uscita, ricerca sul sito, video, download. Consigliati: nomi e parametri standard di Google, utili a report e funzionalità. Personalizzati: azioni che solo il tuo business definisce.", "href": "/faq#qual-e-la-differenza-tra-eventi-automatici-misurazione-avanzata-eventi-c"}, {"id": "perche-google-analytics-invia-page-view-all-avvio-del-tag", "q": "Perché Google Analytics invia page_view all'avvio del tag?", "a": "Perché la configurazione del tag Google manda di default un hit page_view , salvo disattivarlo con send_page_view: false . Si disattiva nelle SPA e quando il pageview lo pubblica il dataLayer, come spiegato nella guida DataLayer .", "href": "/faq#perche-google-analytics-invia-page-view-all-avvio-del-tag"}, {"id": "come-si-invia-un-evento-con-gtag-js-e-quali-parametri-accetta", "q": "Come si invia un evento con gtag.js e quali parametri accetta?", "a": "Sintassi: gtag('event', 'nome_evento', { parametro: valore }) . Il secondo argomento è il nome evento. Il terzo è un oggetto di parametri evento oppure di instradamento verso una destinazione.", "href": "/faq#come-si-invia-un-evento-con-gtag-js-e-quali-parametri-accetta"}, {"id": "qual-e-la-differenza-tra-parametri-evento-e-proprieta-utente", "q": "Qual è la differenza tra parametri evento e proprietà utente?", "a": "I parametri evento descrivono quella singola occorrenza: currency , value , transaction_id , search_term . Le proprietà utente descrivono chi compie l'azione e restano sulle interazioni successive: piano, tipo cliente, area.", "href": "/faq#qual-e-la-differenza-tra-parametri-evento-e-proprieta-utente"}, {"id": "come-si-tracciano-le-conversioni-cioe-gli-eventi-chiave-in-google-analyt", "q": "Come si tracciano le conversioni, cioè gli eventi chiave, in Google Analytics?", "a": "Si invia l'evento con nome e parametri corretti, poi lo si marca come evento chiave nella proprietà GA4. Nomi tipici: purchase , generate_lead , sign_up . Per telefono, email e WhatsApp il segnale parte dai container Tracking Click Telefono , TAG Email e Contatti 3-in-1 .", "href": "/faq#come-si-tracciano-le-conversioni-cioe-gli-eventi-chiave-in-google-analyt"}, {"id": "quali-parametri-sono-critici-per-l-evento-purchase", "q": "Quali parametri sono critici per l'evento purchase?", "a": "transaction_id , univoco, per non contare due volte lo stesso ordine. value , numero, non stringa. currency , codice ISO a tre lettere, per esempio EUR . items , con item_id , item_name , price , quantity . Sono gli stessi campi del Tracker E-commerce .", "href": "/faq#quali-parametri-sono-critici-per-l-evento-purchase"}, {"id": "perche-transaction-id-deve-essere-univoco-nell-evento-purchase", "q": "Perché transaction_id deve essere univoco nell'evento purchase?", "a": "Perché GA4 deduplica gli ordini con lo stesso id. Un ricarico della thank-you page o un doppio invio non devono diventare due acquisti.", "href": "/faq#perche-transaction-id-deve-essere-univoco-nell-evento-purchase"}, {"id": "come-e-fatto-l-array-items-negli-eventi-e-commerce", "q": "Come è fatto l'array items negli eventi e-commerce?", "a": "È una lista di oggetti. Ogni oggetto è un articolo dell'azione ( view_item , add_to_cart , begin_checkout , purchase ). Campi utili: item_id , item_name , item_brand , item_category , price , quantity , index .", "href": "/faq#come-e-fatto-l-array-items-negli-eventi-e-commerce"}, {"id": "qual-e-la-differenza-tra-view-item-list-e-select-item", "q": "Qual è la differenza tra view_item_list e select_item?", "a": "view_item_list misura la vista di una griglia o categoria, con item_list_id e item_list_name . select_item misura il clic su un articolo di quell'elenco, prima della scheda prodotto.", "href": "/faq#qual-e-la-differenza-tra-view-item-list-e-select-item"}, {"id": "come-si-traccia-il-funnel-di-acquisto-con-gli-eventi-consigliati", "q": "Come si traccia il funnel di acquisto con gli eventi consigliati?", "a": "In sequenza, pubblicati dal dataLayer e non da selettori CSS del tema: view_item add_to_cart view_cart begin_checkout add_shipping_info e add_payment_info purchase Il pacchetto che li copre è il Tracker E-commerce . Il livello dati è nella guida DataLayer .", "href": "/faq#come-si-traccia-il-funnel-di-acquisto-con-gli-eventi-consigliati"}, {"id": "cosa-succede-se-value-o-price-arrivano-come-stringa-per-esempio-99-00", "q": "Cosa succede se value o price arrivano come stringa, per esempio \"99.00\"?", "a": "Report e metriche monetarie possono sommare male o scartare il valore. value , price e quantity vanno inviati come numeri.", "href": "/faq#cosa-succede-se-value-o-price-arrivano-come-stringa-per-esempio-99-00"}, {"id": "come-si-gestiscono-i-rimborsi-in-google-analytics", "q": "Come si gestiscono i rimborsi in Google Analytics?", "a": "Con l'evento refund e lo stesso transaction_id dell'ordine originale, più currency e value rimborsato, oppure items se il rimborso è parziale.", "href": "/faq#come-si-gestiscono-i-rimborsi-in-google-analytics"}, {"id": "come-si-inviano-gli-eventi-di-lead-generation-in-modo-standard", "q": "Come si inviano gli eventi di lead generation in modo standard?", "a": "Con eventi consigliati: generate_lead (anche con currency e value stimato) e, nei flussi di qualifica, qualify_lead o close_lead . Il click su telefono, mailto e WhatsApp resta un evento a sé: vedi Contatti 3-in-1 .", "href": "/faq#come-si-inviano-gli-eventi-di-lead-generation-in-modo-standard"}, {"id": "come-si-tracciano-le-single-page-application-dove-non-c-e-un-nuovo-caric", "q": "Come si tracciano le Single Page Application, dove non c'è un nuovo caricamento HTTP?", "a": "Si spegne il page_view automatico se il primo hit farebbe doppio, e si invia un page_view a ogni cambio vista con page_location e page_title aggiornati. In GTM lo stesso risultato arriva da un dataLayer.push con event dedicato. Dettaglio installazione: DataLayer .", "href": "/faq#come-si-tracciano-le-single-page-application-dove-non-c-e-un-nuovo-caric"}, {"id": "qual-e-la-differenza-tra-il-tag-nativo-ga4-in-gtm-e-gtag-event", "q": "Qual è la differenza tra il tag nativo GA4 in GTM e gtag('event', ...)?", "a": "Nel tag nativo mappi parametri e variabili nell'interfaccia, di solito dopo un dataLayer.push . Con gtag('event', ...) la chiamata è nello script di pagina. I due insieme, sullo stesso evento, duplicano gli hit.", "href": "/faq#qual-e-la-differenza-tra-il-tag-nativo-ga4-in-gtm-e-gtag-event"}, {"id": "come-si-evita-di-mandare-dati-personali-in-chiaro-nei-parametri-ga4", "q": "Come si evita di mandare dati personali in chiaro nei parametri GA4?", "a": "Si sanitizza a monte, prima del push. Niente email, telefono o altri dati identificativi in URL, nomi evento o parametri. Il consenso su questi flussi è nella guida Consent Mode .", "href": "/faq#come-si-evita-di-mandare-dati-personali-in-chiaro-nei-parametri-ga4"}, {"id": "cosa-significa-registrare-un-parametro-come-dimensione-o-metrica-persona", "q": "Cosa significa registrare un parametro come dimensione o metrica personalizzata?", "a": "GA4 riceve il parametro subito, ma nei report e nelle esplorazioni lo vedi solo dopo aver creato la dimensione o la metrica personalizzata in proprietà.", "href": "/faq#cosa-significa-registrare-un-parametro-come-dimensione-o-metrica-persona"}, {"id": "come-si-tracciano-moduli-e-download-di-file", "q": "Come si tracciano moduli e download di file?", "a": "file_download con misurazione avanzata, oppure un evento dedicato con file_name , file_extension , link_url . form_start e form_submit , o un evento custom solo a submit confermato, non al semplice clic sul bottone.", "href": "/faq#come-si-tracciano-moduli-e-download-di-file"}, {"id": "quali-regole-di-nome-rispettare-per-eventi-e-parametri", "q": "Quali regole di nome rispettare per eventi e parametri?", "a": "snake_case minuscolo, senza spazi. Niente prefissi riservati: ga_ , google_ , firebase_ . Lo stesso nome su web e app, altrimenti i report cross-platform non si uniscono.", "href": "/faq#quali-regole-di-nome-rispettare-per-eventi-e-parametri"}, {"id": "come-si-verifica-che-un-evento-arrivi-con-i-parametri-giusti", "q": "Come si verifica che un evento arrivi con i parametri giusti?", "a": "Con DebugView in Google Analytics, insieme all'Anteprima di Tag Manager o a Tag Assistant. Si controlla il singolo evento e ogni parametro allegato, non solo il totale del report.", "href": "/faq#come-si-verifica-che-un-evento-arrivi-con-i-parametri-giusti"}, {"id": "che-legame-c-e-tra-gli-eventi-ga4-e-il-remarketing-in-google-ads", "q": "Che legame c'è tra gli eventi GA4 e il remarketing in Google Ads?", "a": "Se le proprietà sono collegate e i segnali pubblicitari sono consentiti, eventi e pubblici di GA4 si importano in Google Ads per offerte e remarketing. Il remarketing di prodotto, con id del feed, è il Dynamic Remarketing , spiegato anche nel tag nativo Google Ads .", "href": "/faq#che-legame-c-e-tra-gli-eventi-ga4-e-il-remarketing-in-google-ads"}, {"id": "cosa-succede-se-un-evento-parte-prima-che-il-tag-sia-pronto-o-prima-dell", "q": "Cosa succede se un evento parte prima che il tag sia pronto o prima dell'aggiornamento del consenso?", "a": "Senza coda o senza Consent Mode l'hit può essere scartato, oppure partire con uno stato di consenso restrittivo. Con GTM o gtag e il Consent Mode , la richiesta segue lo stato applicato.", "href": "/faq#cosa-succede-se-un-evento-parte-prima-che-il-tag-sia-pronto-o-prima-dell"}, {"id": "come-si-gestiscono-piu-proprieta-con-lo-stesso-datalayer", "q": "Come si gestiscono più proprietà con lo stesso dataLayer?", "a": "Instradando ogni tag verso il proprio Measurement ID G-XXXX , in base al trigger o al parametro di destinazione. La coda resta una sola, le destinazioni no.", "href": "/faq#come-si-gestiscono-piu-proprieta-con-lo-stesso-datalayer"}, {"id": "perche-allineare-i-nomi-evento-tra-sito-e-app", "q": "Perché allineare i nomi evento tra sito e app?", "a": "Per leggere purchase o sign_up come la stessa azione su web e app. Nomi diversi spezzano funnel e pubblici.", "href": "/faq#perche-allineare-i-nomi-evento-tra-sito-e-app"}, {"id": "come-si-evita-di-riempire-la-pagina-di-eventi-ridondanti", "q": "Come si evita di riempire la pagina di eventi ridondanti?", "a": "Si scrive prima la tassonomia: solo eventi che servono ad analisi, funnel, conversioni o offerte. Gli attributi vanno nei parametri, non in dieci nomi evento quasi uguali.", "href": "/faq#come-si-evita-di-riempire-la-pagina-di-eventi-ridondanti"}, {"id": "qual-e-la-differenza-tra-un-evento-di-conversione-google-ads-e-un-evento", "q": "Qual è la differenza tra un evento di conversione Google Ads e un evento di remarketing?", "a": "La conversione registra un'azione di valore (acquisto, lead, chiamata, iscrizione) e alimenta i report e le offerte, per esempio Target CPA o Target ROAS. Il remarketing raccoglie segnali di navigazione o di prodotto per costruire pubblici. Il caso catalogo è il Dynamic Remarketing .", "href": "/faq#qual-e-la-differenza-tra-un-evento-di-conversione-google-ads-e-un-evento"}, {"id": "come-si-invia-una-conversione-google-ads-con-gtag-js", "q": "Come si invia una conversione Google Ads con gtag.js?", "a": "Con gtag('event', 'conversion', { send_to: 'AW-CONVERSION_ID/CONVERSION_LABEL', value: 0, currency: 'EUR', transaction_id: '...' }) . In GTM lo stesso invio si fa col tag nativo, non con un HTML personalizzato.", "href": "/faq#come-si-invia-una-conversione-google-ads-con-gtag-js"}, {"id": "a-cosa-serve-il-parametro-send-to", "q": "A cosa serve il parametro send_to?", "a": "Indica l'account AW-... e l'etichetta di conversione a cui attribuire l'azione. Senza send_to preciso, un sito con più account manda il segnale alla destinazione sbagliata.", "href": "/faq#a-cosa-serve-il-parametro-send-to"}, {"id": "quando-usare-transaction-id-anche-nelle-conversioni-google-ads", "q": "Quando usare transaction_id anche nelle conversioni Google Ads?", "a": "Sugli acquisti e su ogni azione che l'utente può ripetere ricaricando la pagina. Lo stesso id impedisce che la thank-you page conti due conversioni.", "href": "/faq#quando-usare-transaction-id-anche-nelle-conversioni-google-ads"}, {"id": "come-funzionano-le-conversioni-avanzate-e-come-si-passano-i-dati-utente", "q": "Come funzionano le conversioni avanzate e come si passano i dati utente?", "a": "Aggiungono al tag di conversione dati forniti dall'utente (email, telefono, nome, indirizzo), trattati secondo le specifiche Google, per recuperare conversioni che il solo cookie non vede. Non vanno messi in chiaro nei parametri di GA4 . Il consenso pubblicitario è in Consent Mode .", "href": "/faq#come-funzionano-le-conversioni-avanzate-e-come-si-passano-i-dati-utente"}, {"id": "come-si-inviano-i-dati-utente-in-gtm-lato-server-per-google-ads", "q": "Come si inviano i dati utente in GTM lato server per Google Ads?", "a": "Con una variabile User-provided data collegata al tag Google, e con il tag Google Ads User-provided Data Event nel server container, usando il Conversion ID corretto.", "href": "/faq#come-si-inviano-i-dati-utente-in-gtm-lato-server-per-google-ads"}, {"id": "cos-e-il-remarketing-dinamico-e-in-cosa-differisce-da-quello-standard", "q": "Cos'è il remarketing dinamico e in cosa differisce da quello standard?", "a": "Il remarketing standard usa liste di pagine visitate. Quello dinamico manda parametri di catalogo ( value , currency , items con id e google_business_vertical ) per mostrare gli articoli visti o abbandonati. È il perimetro del Dynamic Remarketing .", "href": "/faq#cos-e-il-remarketing-dinamico-e-in-cosa-differisce-da-quello-standard"}, {"id": "quali-parametri-chiede-il-remarketing-dinamico-retail", "q": "Quali parametri chiede il remarketing dinamico retail?", "a": "send_to verso la destinazione Ads corretta. value e currency . items , e in ogni elemento un id identico all'id prodotto del feed Merchant Center. google_business_vertical , per il retail di solito retail .", "href": "/faq#quali-parametri-chiede-il-remarketing-dinamico-retail"}, {"id": "cosa-succede-se-l-id-prodotto-non-coincide-con-il-feed-merchant-center", "q": "Cosa succede se l'id prodotto non coincide con il feed Merchant Center?", "a": "Google Ads non abbina l'utente all'articolo del catalogo. L'annuncio dinamico non si personalizza, oppure usa un fallback generico.", "href": "/faq#cosa-succede-se-l-id-prodotto-non-coincide-con-il-feed-merchant-center"}, {"id": "perche-i-modelli-di-tag-nativi-google-ads-in-gtm-e-non-un-tag-html-perso", "q": "Perché i modelli di tag nativi Google Ads in GTM e non un tag HTML personalizzato?", "a": "I modelli nativi formattano i parametri, parlano col Conversion Linker, rispettano il Consent Mode e restano allineati alle funzioni Ads più recenti. Un HTML personalizzato queste cose le reinventa, e di solito le rompe.", "href": "/faq#perche-i-modelli-di-tag-nativi-google-ads-in-gtm-e-non-un-tag-html-perso"}, {"id": "come-si-evita-la-doppia-conversione-se-il-sito-ha-sia-gtag-js-sia-gtm", "q": "Come si evita la doppia conversione se il sito ha sia gtag.js sia GTM?", "a": "Si tiene un solo sistema, di preferenza GTM con tag nativi, e si toglie l'altro invio dello stesso evento sullo stesso trigger. Due tag sulla stessa thank-you page contano due conversioni.", "href": "/faq#come-si-evita-la-doppia-conversione-se-il-sito-ha-sia-gtag-js-sia-gtm"}, {"id": "come-si-tracciano-azioni-che-non-ricaricano-la-pagina-come-un-form-ajax-", "q": "Come si tracciano azioni che non ricaricano la pagina, come un form AJAX o un clic sul telefono?", "a": "Il trigger deve ascoltare un event del dataLayer emesso solo dopo la conferma: per esempio form_submitted o phone_click . Il container già pronto per il numero è il Tracking Click Telefono ; per telefono, email e WhatsApp insieme, Contatti 3-in-1 .", "href": "/faq#come-si-tracciano-azioni-che-non-ricaricano-la-pagina-come-un-form-ajax-"}, {"id": "a-cosa-servono-value-e-currency-in-google-ads", "q": "A cosa servono value e currency in Google Ads?", "a": "Misurano il ritorno economico della conversione e alimentano le strategie basate sul valore: Massimizza il valore di conversione e Target ROAS. Senza valuta, il valore non è confrontabile.", "href": "/faq#a-cosa-servono-value-e-currency-in-google-ads"}, {"id": "come-si-distinguono-valori-variabili-e-valori-fissi", "q": "Come si distinguono valori variabili e valori fissi?", "a": "Per ecommerce e preventivi il valore calcolato sta nel dataLayer, transazione per transazione: è il caso del Tracker E-commerce . Per un lead a valore costante si imposta un fisso nella conversione Ads, e lo si ripete identico.", "href": "/faq#come-si-distinguono-valori-variabili-e-valori-fissi"}, {"id": "che-differenza-c-e-tra-importare-una-conversione-da-ga4-e-usare-il-tag-n", "q": "Che differenza c'è tra importare una conversione da GA4 e usare il tag nativo Google Ads?", "a": "Il tag nativo manda il segnale direttamente a Google Ads, con Conversion Linker e conversioni avanzate. L'import da GA4 dipende dall'evento chiave e dal collegamento tra i due prodotti, ed è meno adatto quando ti serve il clic pubblicitario di prima parte. Il modello del tag nativo è il tema di questa guida.", "href": "/faq#che-differenza-c-e-tra-importare-una-conversione-da-ga4-e-usare-il-tag-n"}, {"id": "come-si-verifica-che-una-conversione-google-ads-parta-senza-errori", "q": "Come si verifica che una conversione Google Ads parta senza errori?", "a": "In Anteprima di GTM o in Tag Assistant controlli trigger, variabili e stato del consenso. In Rete cerchi le richieste verso i domini pubblicitari Google, non solo il nome del tag in verde.", "href": "/faq#come-si-verifica-che-una-conversione-google-ads-parta-senza-errori"}, {"id": "cosa-succede-se-il-tag-di-conversione-scatta-prima-che-le-variabili-sian", "q": "Cosa succede se il tag di conversione scatta prima che le variabili siano pronte?", "a": "value o transaction_id partono vuoti. Valore, valuta e id devono stare nello stesso oggetto del dataLayer.push che emette l' event , oppure essere già nello stato prima di quel push. La coda è spiegata nella guida DataLayer .", "href": "/faq#cosa-succede-se-il-tag-di-conversione-scatta-prima-che-le-variabili-sian"}, {"id": "come-si-gestisce-il-consenso-sui-tag-di-conversione-e-remarketing", "q": "Come si gestisce il consenso sui tag di conversione e remarketing?", "a": "Con il Consent Mode: ad_storage , ad_user_data per i dati utente usati in pubblicità, ad_personalization per remarketing e annunci personalizzati. Il dettaglio dei comandi default e update è nella guida Consent Mode . Il pacchetto è Consent Mode v2 .", "href": "/faq#come-si-gestisce-il-consenso-sui-tag-di-conversione-e-remarketing"}, {"id": "si-puo-mandare-un-evento-a-un-solo-account-google-ads", "q": "Si può mandare un evento a un solo account Google Ads?", "a": "Sì. send_to sul tag o sull'evento limita la destinazione a quell'account e a quell'etichetta. Gli altri account collegati in pagina non ricevono quella conversione.", "href": "/faq#si-puo-mandare-un-evento-a-un-solo-account-google-ads"}, {"id": "che-rapporto-c-e-tra-il-tag-google-su-tutte-le-pagine-e-la-precisione-de", "q": "Che rapporto c'è tra il tag Google su tutte le pagine e la precisione delle conversioni?", "a": "Il tag presente su tutto il sito mantiene cookie e identificativi di prima parte lungo la sessione. Senza, il Conversion Linker non vede il clic sulla landing e l'attribuzione si accorcia.", "href": "/faq#che-rapporto-c-e-tra-il-tag-google-su-tutte-le-pagine-e-la-precisione-de"}, {"id": "cos-e-il-conversion-linker-e-a-cosa-serve", "q": "Cos'è il Conversion Linker e a cosa serve?", "a": "Memorizza in un cookie di prima parte i dati del clic pubblicitario, come il gclid , così il tag di conversione li ritrova quando l'azione avviene, anche pagine dopo.", "href": "/faq#cos-e-il-conversion-linker-e-a-cosa-serve"}, {"id": "perche-il-conversion-linker-e-indispensabile-con-i-limiti-ai-cookie-di-t", "q": "Perché il Conversion Linker è indispensabile con i limiti ai cookie di terze parti?", "a": "I browser bloccano o accorciano i cookie di terze parti. Salvare il clic sul dominio del sito rende la conversione leggibile senza quel cookie di terza parte.", "href": "/faq#perche-il-conversion-linker-e-indispensabile-con-i-limiti-ai-cookie-di-t"}, {"id": "su-quali-pagine-deve-attivarsi-il-conversion-linker-in-gtm", "q": "Su quali pagine deve attivarsi il Conversion Linker in GTM?", "a": "Su tutte, con attivatore All Pages. Qualsiasi landing che riceve un clic pubblicitario deve poter salvare subito il parametro.", "href": "/faq#su-quali-pagine-deve-attivarsi-il-conversion-linker-in-gtm"}, {"id": "come-funziona-il-conversion-linker-nel-tagging-lato-server", "q": "Come funziona il Conversion Linker nel tagging lato server?", "a": "Nel server container il tag Conversion Linker, di solito su All Pages, scrive e legge i cookie di prima parte legati al dominio del server di tagging.", "href": "/faq#come-funziona-il-conversion-linker-nel-tagging-lato-server"}, {"id": "qual-e-la-differenza-tra-cookie-di-prima-parte-e-di-terze-parti", "q": "Qual è la differenza tra cookie di prima parte e di terze parti?", "a": "Il cookie di prima parte è impostato dal dominio della pagina che stai visitando. Quello di terze parti è impostato da un dominio diverso da quello della pagina.", "href": "/faq#qual-e-la-differenza-tra-cookie-di-prima-parte-e-di-terze-parti"}, {"id": "perche-i-cookie-di-prima-parte-reggono-meglio-la-misura-di-oggi", "q": "Perché i cookie di prima parte reggono meglio la misura di oggi?", "a": "Appartengono al sito visitato e sfuggono al blocco generalizzato dei cookie di terze parti. Restano però soggetti al consenso e alle scadenze imposte dal browser.", "href": "/faq#perche-i-cookie-di-prima-parte-reggono-meglio-la-misura-di-oggi"}, {"id": "come-browser-e-server-possono-comunque-limitare-i-cookie-di-prima-parte", "q": "Come browser e server possono comunque limitare i cookie di prima parte?", "a": "Con ITP e tetti di durata, con attributi sbagliati ( Domain , Path , SameSite , Secure ) e con il consenso negato su analytics_storage o ad_storage . Vedi Consent Mode .", "href": "/faq#come-browser-e-server-possono-comunque-limitare-i-cookie-di-prima-parte"}, {"id": "che-legame-c-e-tra-cookie-di-prima-parte-analytics-storage-e-il-client-i", "q": "Che legame c'è tra cookie di prima parte, analytics_storage e il client id di GA4?", "a": "Se analytics_storage è consentito, GA4 legge e scrive cookie di prima parte per riconoscere utente e sessione. Se è negato, non usa quello storage per identificarli. Guida eventi: Google Analytics 4 .", "href": "/faq#che-legame-c-e-tra-cookie-di-prima-parte-analytics-storage-e-il-client-i"}, {"id": "che-legame-c-e-tra-cookie-di-prima-parte-ad-storage-e-conversion-linker", "q": "Che legame c'è tra cookie di prima parte, ad_storage e Conversion Linker?", "a": "Linker e tag pubblicitari conservano il clic nello storage di prima parte. Se ad_storage è negato, quella scrittura è limitata e la conversione non può appoggiarsi al cookie pubblicitario.", "href": "/faq#che-legame-c-e-tra-cookie-di-prima-parte-ad-storage-e-conversion-linker"}, {"id": "in-che-senso-il-tag-google-misura-anche-quando-i-cookie-sono-limitati", "q": "In che senso il tag Google misura anche quando i cookie sono limitati?", "a": "Mette insieme segnali di prima parte, parametri di linker nell'URL, Consent Mode e modellazione. Non è un modo per ignorare un rifiuto: è continuità di misura dentro lo stato di consenso.", "href": "/faq#in-che-senso-il-tag-google-misura-anche-quando-i-cookie-sono-limitati"}, {"id": "cos-e-la-misurazione-interdominio-e-quando-serve", "q": "Cos'è la misurazione interdominio e quando serve?", "a": "Serve quando il percorso attraversa due domini distinti, per esempio il sito e un checkout esterno, e vuoi la stessa sessione invece di un nuovo utente o di un auto-referral.", "href": "/faq#cos-e-la-misurazione-interdominio-e-quando-serve"}, {"id": "che-differenza-c-e-tra-sottodomini-e-domini-diversi", "q": "Che differenza c'è tra sottodomini e domini diversi?", "a": "www.esempio.it e shop.esempio.it condividono il dominio padre e, se il cookie è impostato su .esempio.it , anche i cookie di prima parte. dominio-a.it e dominio-b.com no: serve la decorazione dei link.", "href": "/faq#che-differenza-c-e-tra-sottodomini-e-domini-diversi"}, {"id": "come-il-tag-google-mantiene-l-identita-da-dominio-a-com-a-dominio-b-com", "q": "Come il tag Google mantiene l'identità da dominio-a.com a dominio-b.com?", "a": "Decora link e form in uscita con un parametro _gl . Il dominio di arrivo lo legge e salva lo stato nei propri cookie di prima parte.", "href": "/faq#come-il-tag-google-mantiene-l-identita-da-dominio-a-com-a-dominio-b-com"}, {"id": "quali-errori-fanno-fallire-il-cross-domain", "q": "Quali errori fanno fallire il cross-domain?", "a": "Un dominio manca dall'elenco di configurazione. Un redirect lato server elimina la query, quindi anche _gl . Uno script intercetta il clic e naviga senza lasciare decorare il link.", "href": "/faq#quali-errori-fanno-fallire-il-cross-domain"}, {"id": "come-si-verifica-il-passaggio-tra-pagine-amp-e-pagine-non-amp", "q": "Come si verifica il passaggio tra pagine AMP e pagine non AMP?", "a": "In finestra anonima, o dopo aver cancellato i cookie, controlli che cid e l'eventuale gclid viaggino nel parametro _gl e coincidano sulla pagina finale. I redirect in mezzo sono il punto che si rompe per primo.", "href": "/faq#come-si-verifica-il-passaggio-tra-pagine-amp-e-pagine-non-amp"}, {"id": "come-influiscono-i-redirect-301-e-302-sul-conversion-linker-e-sul-cross-", "q": "Come influiscono i redirect 301 e 302 sul Conversion Linker e sul cross-domain?", "a": "Se il redirect non conserva la query string, gclid e _gl si perdono. La catena va provata sull'URL reale di arrivo, non solo sul link originale.", "href": "/faq#come-influiscono-i-redirect-301-e-302-sul-conversion-linker-e-sul-cross-"}, {"id": "come-si-controllano-i-cookie-durante-il-debug", "q": "Come si controllano i cookie durante il debug?", "a": "In Strumenti per sviluppatori: scheda Application, elenco Cookie, e scheda Network per vedere dominio, scadenza e payload delle richieste.", "href": "/faq#come-si-controllano-i-cookie-durante-il-debug"}, {"id": "qual-e-la-checklist-di-un-tagging-robusto-su-datalayer-ga4-e-google-ads", "q": "Qual è la checklist di un tagging robusto su dataLayer, GA4 e Google Ads?", "a": "Inizializzare window.dataLayer una sola volta, in alto, senza riassegnarlo. Guida: DataLayer . Eventi con parametri tipizzati, numeri davvero numeri. Guida: GA4 . Tag nativi, non HTML personalizzato, per Ads e Analytics. Consent Mode con default prima dei tag e update dal CMP. Guida: Consent Mode .", "href": "/faq#qual-e-la-checklist-di-un-tagging-robusto-su-datalayer-ga4-e-google-ads"}, {"id": "cos-e-il-consent-mode-nella-tag-platform-di-google", "q": "Cos'è il Consent Mode nella Tag Platform di Google?", "a": "È il modo in cui i tag Google ricevono lo stato del consenso e adattano cookie, identificativi e ping. Non sostituisce il banner: legge la scelta che il banner ha raccolto. Il pacchetto di implementazione è Consent Mode v2 .", "href": "/faq#cos-e-il-consent-mode-nella-tag-platform-di-google"}, {"id": "quali-parametri-di-consenso-gestisce-il-consent-mode", "q": "Quali parametri di consenso gestisce il Consent Mode?", "a": "ad_storage : storage pubblicitario. analytics_storage : storage di analisi. ad_user_data : dati utente per finalità pubblicitarie. ad_personalization : personalizzazione degli annunci e remarketing. Dove servono: functionality_storage , personalization_storage , security_storage .", "href": "/faq#quali-parametri-di-consenso-gestisce-il-consent-mode"}, {"id": "qual-e-la-differenza-tra-default-e-update", "q": "Qual è la differenza tra default e update?", "a": "default è lo stato iniziale, prima che i tag partano. Nelle aree a consenso preventivo è spesso denied . update arriva quando la persona accetta o rifiuta nel CMP e sostituisce quello stato.", "href": "/faq#qual-e-la-differenza-tra-default-e-update"}, {"id": "perche-il-default-va-impostato-prima-che-partano-i-tag", "q": "Perché il default va impostato prima che partano i tag?", "a": "Perché un tag partito prima del default può scrivere cookie in contrasto con la scelta iniziale. I tag dello stesso evento devono leggere un solo stato, coerente. L'ordine rispetto alla coda è quello del DataLayer .", "href": "/faq#perche-il-default-va-impostato-prima-che-partano-i-tag"}, {"id": "perche-il-consent-mode-non-si-configura-con-un-tag-html-personalizzato", "q": "Perché il Consent Mode non si configura con un tag HTML personalizzato?", "a": "Un HTML personalizzato scatta in un momento non allineato alla coda e alla valutazione dei tag. Si usano le API di consenso di GTM o gtag('consent', ...) e l'integrazione del CMP.", "href": "/faq#perche-il-consent-mode-non-si-configura-con-un-tag-html-personalizzato"}, {"id": "come-fa-gtm-a-far-vedere-lo-stesso-aggiornamento-a-tutti-i-tag", "q": "Come fa GTM a far vedere lo stesso aggiornamento a tutti i tag?", "a": "Con le API di consenso e con i controlli già presenti nei modelli di tag nativi. L'update viene elaborato nell'ordine corretto rispetto ai messaggi in coda, non \"quando capita\".", "href": "/faq#come-fa-gtm-a-far-vedere-lo-stesso-aggiornamento-a-tutti-i-tag"}, {"id": "cosa-succede-se-analytics-storage-e-denied", "q": "Cosa succede se analytics_storage è denied?", "a": "I tag di Google Analytics 4 non possono leggere o scrivere i cookie di analisi usati per riconoscere utente e sessione. Possono restare ping senza cookie, secondo la configurazione del Consent Mode.", "href": "/faq#cosa-succede-se-analytics-storage-e-denied"}, {"id": "cosa-succede-se-ad-storage-ad-user-data-o-ad-personalization-sono-denied", "q": "Cosa succede se ad_storage, ad_user_data o ad_personalization sono denied?", "a": "Si limita lo storage pubblicitario, l'invio di dati utente a fini ads o la personalizzazione, remarketing incluso. I tag di Google Ads restano conformi alla scelta. La modellazione, dove prevista, non equivale a ignorare il rifiuto.", "href": "/faq#cosa-succede-se-ad-storage-ad-user-data-o-ad-personalization-sono-denied"}, {"id": "cos-e-una-cmp-e-come-si-collega-alla-tag-platform", "q": "Cos'è una CMP e come si collega alla Tag Platform?", "a": "È il sistema che raccoglie e conserva la scelta. Si integra con GTM o gtag.js emettendo default e update , ed eventualmente il TCF v2.2. Senza questo ponte, il banner e i tag non si parlano: è il problema che chiude Consent Mode v2 .", "href": "/faq#cos-e-una-cmp-e-come-si-collega-alla-tag-platform"}, {"id": "quali-problemi-capitano-con-le-implementazioni-iab-tcf", "q": "Quali problemi capitano con le implementazioni IAB TCF?", "a": "Stringhe o purpose non allineate, CMP che arriva dopo i tag, supporto TCF acceso a metà nei tag Google. Tag Assistant mostra lo stato letto davvero, non quello promesso dal plugin.", "href": "/faq#quali-problemi-capitano-con-le-implementazioni-iab-tcf"}, {"id": "come-si-verifica-il-consent-mode-in-tag-assistant", "q": "Come si verifica il Consent Mode in Tag Assistant?", "a": "Nella timeline, per ogni evento, si leggono Default e Update di ciascun parametro. Un tag non deve partire con uno stato diverso dalle regole impostate per quel momento.", "href": "/faq#come-si-verifica-il-consent-mode-in-tag-assistant"}, {"id": "che-ruolo-ha-il-consent-mode-nel-tagging-lato-server", "q": "Che ruolo ha il Consent Mode nel tagging lato server?", "a": "Lo stato viaggia anche verso il server container. I tag che partono dal server devono rispettare la stessa scelta, non una seconda policy.", "href": "/faq#che-ruolo-ha-il-consent-mode-nel-tagging-lato-server"}], "products": [{"id": "phone", "name": "Tracking Click Telefono", "price": "€150", "href": "/shop/tracking-click-telefono", "keys": ["telefono", "tel", "chiamata", "chiamate", "numero", "click telefono"], "why": "Misura i click sui link tel: e li invia a Google Ads e GA4. Il container è pronto: non va ricostruito il trigger."}, {"id": "email", "name": "TAG Email", "price": "€150", "href": "/shop/tag-email", "keys": ["email", "mailto", "mail"], "why": "Traccia i click sui link mailto:. Serve se la lead arriva scrivendo, non compilando un form."}, {"id": "facebook", "name": "TAG Facebook", "price": "€150", "href": "/shop/tag-facebook", "keys": ["facebook", "meta", "fbq", "pixel"], "why": "Traccia i click che escono verso Facebook o Meta. Utile se la campagna manda traffico e vuoi contare il ritorno sul profilo."}, {"id": "instagram", "name": "TAG Instagram", "price": "€150", "href": "/shop/tag-instagram", "keys": ["instagram", "ig"], "why": "Conta i click verso Instagram. Ha senso se il profilo è un passaggio delle campagne, non solo una vetrina."}, {"id": "linkedin", "name": "TAG LinkedIn", "price": "€150", "href": "/shop/tag-linkedin", "keys": ["linkedin", "b2b"], "why": "Misura i click verso LinkedIn, il caso tipico dei lead B2B che non comprano in pagina."}, {"id": "tre", "name": "Contatti 3-in-1", "price": "€350", "href": "/shop/contatti-3in1", "keys": ["whatsapp", "3 in 1", "3-in-1", "tre contatti", "telefono email"], "why": "Un solo container per telefono, email e WhatsApp. Conviene se misuri più di un contatto, invece di comprare i tag uno a uno."}, {"id": "social", "name": "Tracking Social 6-in-1", "price": "€450", "href": "/shop/tracking-social-6in1", "keys": ["6 in 1", "6-in-1", "tutti i social", "tiktok", "youtube", "pinterest"], "why": "Copre più reti in un container. Costa meno che prendere i tag social separati, se ti servono insieme."}, {"id": "ecom", "name": "Tracker E-commerce", "price": "Preventivo", "href": "/shop/tracker-ecommerce", "keys": ["ecommerce", "e-commerce", "shopify", "woocommerce", "prestashop", "magento", "carrello", "purchase", "acquisto", "ordini", "checkout"], "why": "Il funnel purchase dipende dal CMS e dal dataLayer: non è un JSON standard. Sulla scheda c’è il form con la piattaforma."}, {"id": "remark", "name": "Dynamic Remarketing", "price": "Preventivo", "href": "/shop/dynamic-remarketing", "keys": ["remarketing", "retargeting", "merchant", "feed", "dinamico"], "why": "Serve se gli annunci devono mostrare il prodotto visto. Va allineato al feed, per questo è su preventivo."}, {"id": "consent", "name": "Consent Mode v2", "price": "Preventivo", "href": "/shop/consent-mode-v2", "keys": ["consent", "consenso", "cookie", "cmp", "gdpr", "banner", "iubenda", "cookiebot", "onetrust"], "why": "Collega il banner ai tag Google con default e update. Se i tag partono prima della scelta, la misura e il remarketing si rompono."}, {"id": "h5", "name": "Supporto 5 ore", "price": "€500", "href": "/shop/supporto-5-ore", "keys": ["5 ore", "poche ore", "verifica", "audit breve"], "why": "Pacchetto corto per un controllo: consenso, un contenitore, un evento che non parte."}, {"id": "h10", "name": "Supporto 10 ore", "price": "€900", "href": "/shop/supporto-10-ore", "keys": ["10 ore", "agenzia", "piu clienti", "più clienti"], "why": "Per un intervento più largo o per un’agenzia che ha più di un contenitore da sistemare."}, {"id": "h20", "name": "Supporto 20 ore", "price": "€1.600", "href": "/shop/supporto-20-ore", "keys": ["20 ore", "continuativo", "mensile", "ricorrente"], "why": "Per un affiancamento più lungo, quando il lavoro non sta in una singola scheda prodotto."}], "guides": [{"q": "Architettura dataLayer", "a": "Il dataLayer è la coda che porta eventi e variabili a Google Tag Manager. Va inizializzato una volta, prima dello snippet, e non va riassegnato.", "href": "/datalayer-architettura", "keys": ["datalayer", "data layer", "gtm", "tag manager", "push", "fifo"]}, {"q": "Google Analytics 4", "a": "GA4 distingue eventi automatici, misurazione avanzata, consigliati e personalizzati. Un e-commerce ha bisogno del funnel e dei parametri purchase, non solo della misurazione avanzata.", "href": "/tag-google-analytics-4", "keys": ["ga4", "analytics", "eventi", "debugview"]}, {"q": "Tag nativo Google Ads", "a": "Il tag Ads registra la conversione e il remarketing. Conversion Linker e cookie di prima parte tengono il collegamento con il clic.", "href": "/tag-nativo-google-ads", "keys": ["google ads", "conversion linker", "gclid", "conversione ads", "send_to"]}, {"q": "Consent Mode", "a": "Il Consent Mode non sostituisce il banner. default va prima dei tag, update arriva dalla CMP. I quattro parametri sono ad_storage, analytics_storage, ad_user_data e ad_personalization.", "href": "/consent-mode", "keys": ["consent mode", "consent", "cmp", "gcs"]}, {"q": "Chi siamo", "a": "Easy Tag è lo spin-off del team italiano che ha lavorato sui tag a Google Cracovia. Il lavoro è su GTM, GA4, Ads, dataLayer e consenso.", "href": "/chi-siamo", "keys": ["chi siete", "chi siamo", "team", "cracovia", "google"]}]};
  var STOP = {di:1,a:1,da:1,in:1,con:1,su:1,per:1,il:1,lo:1,la:1,i:1,gli:1,le:1,un:1,una:1,uno:1,che:1,non:1,mi:1,ti:1,si:1,ho:1,hai:1,come:1,cosa:1,quale:1,quali:1,del:1,della:1,dei:1,delle:1,e:1,o:1,ma:1,se:1,nel:1,nella:1,sono:1,sei:1,mio:1,tuo:1,questo:1,questa:1,voglio:1,vorrei:1,serve:1,devo:1,posso:1,sul:1,sulla:1,dallo:1,dalla:1,anche:1,piu:1,gia:1,cioe:1,the:1,of:1};

  function norm(s) {
    return String(s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9\s]/g, " ").replace(/\s+/g, " ").trim();
  }
  function tokens(s) {
    var out = [];
    norm(s).split(" ").forEach(function (w) {
      if (w.length >= 3 && !STOP[w]) out.push(w);
    });
    return out;
  }
  function has(text, key) {
    return norm(text).indexOf(norm(key)) !== -1;
  }
  function esc(s) {
    return String(s).replace(/[&<>"]/g, function (c) {
      if (c === "&") return "&" + "amp;";
      if (c === "<") return "&" + "lt;";
      if (c === ">") return "&" + "gt;";
      return "&" + "quot;";
    });
  }
  function scoreText(query, text) {
    var qt = tokens(query);
    var blob = norm(text);
    var s = 0;
    qt.forEach(function (w) {
      if (blob.indexOf(w) !== -1) s += 1;
    });
    return s;
  }

  function matchProducts(query) {
    var hits = [];
    KB.products.forEach(function (p) {
      var s = 0;
      p.keys.forEach(function (k) {
        if (has(query, k)) s += k.indexOf(" ") !== -1 ? 4 : 2;
      });
      if (s) hits.push({ p: p, s: s });
    });
    hits.sort(function (a, b) { return b.s - a.s; });
    var socialIds = { facebook: 1, instagram: 1, linkedin: 1 };
    var socials = hits.filter(function (h) { return socialIds[h.p.id]; });
    if (socials.length >= 2) {
      hits = hits.filter(function (h) { return !socialIds[h.p.id]; });
      var pack = KB.products.filter(function (p) { return p.id === "social"; })[0];
      hits.unshift({ p: pack, s: 8 });
    }
    var contactish = hits.filter(function (h) { return h.p.id === "phone" || h.p.id === "email"; });
    if (has(query, "whatsapp") && contactish.length) {
      hits = hits.filter(function (h) { return h.p.id !== "phone" && h.p.id !== "email"; });
      var tre = KB.products.filter(function (p) { return p.id === "tre"; })[0];
      hits.unshift({ p: tre, s: 8 });
    }
    var seen = {};
    return hits.filter(function (h) {
      if (seen[h.p.id]) return false;
      seen[h.p.id] = 1;
      return true;
    }).slice(0, 2);
  }

  function bestFaq(query) {
    var best = null;
    KB.faqs.forEach(function (f) {
      var qHits = scoreText(query, f.q);
      var s = qHits * 3 + scoreText(query, f.a);
      if (!best || s > best.s) best = { f: f, s: s, qHits: qHits };
    });
    return best && best.qHits >= 2 ? best : null;
  }
  function bestGuide(query) {
    var best = null;
    KB.guides.forEach(function (g) {
      var s = 0;
      g.keys.forEach(function (k) { if (has(query, k)) s += 3; });
      s += scoreText(query, g.q + " " + g.a);
      if (!best || s > best.s) best = { g: g, s: s };
    });
    return best && best.s >= 3 ? best : null;
  }

  function reply(raw) {
    var query = String(raw || "").trim();
    var n = norm(query);
    if (!n || /^(ciao|salve|buongiorno|buonasera|hey|hello|hi)$/.test(n)) {
      return {
        text: "Ciao. Rispondo con le guide e le FAQ del sito. Dimmi cosa devi misurare: un click, un e-commerce, Google Ads, il consenso, oppure un intervento sul contenitore.",
        cards: [],
        links: [{ label: "Vedi lo shop", href: "/shop" }, { label: "Collaborazione tecnica", href: "/contatti" }]
      };
    }
    if (/prezzo|costo|quanto costa|listino/.test(n) && tokens(query).length <= 3) {
      return {
        text: "I container pronti partono da €150 IVA inclusa. Telefono, email e i singoli social sono €150; Contatti 3-in-1 è €350; Social 6-in-1 è €450. Le ore vanno da €500 a €1.600. E-commerce, remarketing dinamico e Consent Mode sono su preventivo, perché dipendono dal sito.",
        cards: [],
        links: [{ label: "Apri lo shop", href: "/shop" }]
      };
    }
    var collab = /collabor|agenzia|consulen|affianc|personalizz|audit|supporto|ore\b|insieme|intervento/.test(n);
    var products = matchProducts(query);
    var faq = bestFaq(query);
    if (faq && products.length && faq.qHits < 3) faq = null;
    var guide = bestGuide(query);
    var parts = [];
    var cards = [];
    var links = [];

    products.forEach(function (h) { cards.push(h.p); });
    if (faq) {
      parts.push(faq.f.a);
      links.push({ label: "Apri la FAQ", href: faq.f.href });
    } else if (guide && !products.length) {
      parts.push(guide.g.a);
      links.push({ label: "Apri la guida", href: guide.g.href });
    }
    if (collab) {
      parts.push("Se il caso non sta in un container pronto, scrivi dalla pagina Contatti: è il canale per audit e collaborazioni tecniche. Per un controllo già circoscritto c’è il pacchetto da 5 ore.");
      if (!cards.some(function (c) { return c.id === "h5"; })) {
        cards.push(KB.products.filter(function (p) { return p.id === "h5"; })[0]);
      }
      links.push({ label: "Scrivi per una collaborazione", href: "/contatti" });
    }
    cards = cards.slice(0, 2);
    if (cards.length) {
      parts.unshift(cards.length > 1
        ? "In base a quello che hai scritto, queste sono le schede più vicine. Sotto ognuna c’è il motivo."
        : "La scheda più adatta è questa. Sotto c’è perché ti torna utile, non è un consiglio generico.");
    }
    if (!parts.length) {
      parts.push("Su questo punto non c’è una risposta precisa tra le FAQ. Puoi sfogliare le domande, oppure raccontare il sito (CMS, cosa vuoi contare, se hai già un banner cookie) e ti indico la scheda.");
      links.push({ label: "Tutte le FAQ", href: "/faq" });
      links.push({ label: "Contatti", href: "/contatti" });
    } else if (!links.some(function (l) { return l.href === "/shop"; }) && cards.length) {
      links.push({ label: "Shop", href: "/shop" });
    }
    return { text: parts.join(" "), cards: cards, links: links.slice(0, 3) };
  }

  if (typeof document === "undefined") {
    globalThis.ETChat = { reply: reply };
    return;
  }

  var css = ""
    + ".et-chat-btn{position:fixed;right:18px;bottom:18px;z-index:9999;width:58px;height:58px;border:0;border-radius:50%;background:#1182DE;color:#fff;box-shadow:0 8px 24px rgba(17,130,222,.35);cursor:pointer;display:grid;place-items:center}"
    + ".et-chat-btn:focus-visible,.et-chat-send:focus-visible,.et-chat-x:focus-visible,.et-chip:focus-visible{outline:3px solid #0B5CAD;outline-offset:2px}"
    + ".et-chat-panel{position:fixed;right:18px;bottom:86px;z-index:9999;width:min(380px,calc(100vw - 24px));height:min(560px,calc(100vh - 110px));background:#fff;border:1px solid #E8EAED;border-radius:16px;box-shadow:0 16px 50px rgba(0,0,0,.16);display:flex;flex-direction:column;overflow:hidden;font-family:Inter,Arial,sans-serif;color:#202124}"
    + ".et-chat-panel[hidden]{display:none}"
    + ".et-chat-h{background:#1182DE;color:#fff;padding:12px 14px;display:flex;justify-content:space-between;gap:8px;align-items:flex-start}"
    + ".et-chat-h strong{display:block;font-size:15px}.et-chat-h span{display:block;font-size:12px;opacity:.9;font-weight:500}"
    + ".et-chat-x{background:transparent;border:0;color:#fff;font-size:22px;line-height:1;cursor:pointer;padding:0 4px}"
    + ".et-chat-log{flex:1;overflow:auto;padding:12px;background:#F8F9FA;display:flex;flex-direction:column;gap:8px}"
    + ".et-msg{max-width:92%;padding:10px 12px;border-radius:12px;font-size:14px;line-height:1.45}"
    + ".et-msg.bot{background:#fff;border:1px solid #E8EAED;align-self:flex-start}"
    + ".et-msg.user{background:#1182DE;color:#fff;align-self:flex-end}"
    + ".et-card{display:block;margin-top:8px;padding:8px 10px;border-radius:10px;background:#E8F3FC;color:#0B5CAD;text-decoration:none}"
    + ".et-card b{display:block;color:#202124}.et-card i{display:block;font-style:normal;color:#5F6368;font-size:12.5px;margin-top:2px}.et-card em{font-style:normal;font-weight:700}"
    + ".et-links{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}"
    + ".et-links a{font-size:12.5px;font-weight:700;color:#1182DE;text-decoration:none;background:#fff;border:1px solid #D0E8F9;border-radius:99px;padding:4px 8px}"
    + ".et-chips{display:flex;gap:6px;flex-wrap:wrap;padding:8px 12px 0;background:#fff}"
    + ".et-chip{border:1px solid #E8EAED;background:#fff;border-radius:99px;padding:6px 10px;font-size:12.5px;cursor:pointer;color:#202124}"
    + ".et-chat-form{display:flex;gap:8px;padding:10px;border-top:1px solid #E8EAED;background:#fff}"
    + ".et-chat-form input{flex:1;border:1px solid #E8EAED;border-radius:10px;padding:10px;font:inherit;font-size:14px}"
    + ".et-chat-send{background:#1182DE;color:#fff;border:0;border-radius:10px;padding:0 12px;font-weight:700;cursor:pointer}"
    + "@media(max-width:640px){.et-chat-panel{right:12px;bottom:78px;height:min(70vh,560px)}}"
    + "@media(prefers-reduced-motion:reduce){.et-chat-btn,.et-chat-panel{transition:none}}";

  var style = document.createElement("style");
  style.textContent = css;
  document.head.appendChild(style);

  var btn = document.createElement("button");
  btn.type = "button";
  btn.className = "et-chat-btn";
  btn.setAttribute("aria-label", "Apri la chat");
  btn.setAttribute("aria-expanded", "false");
  btn.setAttribute("aria-controls", "et-chat-panel");
  btn.innerHTML = '<svg width="26" height="26" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="#fff" stroke-width="2"><path d="M5 6h14v9H8l-3 3V6z"/></svg>';

  var panel = document.createElement("section");
  panel.id = "et-chat-panel";
  panel.className = "et-chat-panel";
  panel.hidden = true;
  panel.setAttribute("role", "dialog");
  panel.setAttribute("aria-label", "Chat Easy Tag");
  panel.innerHTML = ''
    + '<div class="et-chat-h"><div><strong>Easy Tag</strong><span>Risposte dal sito, per scegliere il container giusto</span></div><button type="button" class="et-chat-x" aria-label="Chiudi chat">×</button></div>'
    + '<div class="et-chips"></div>'
    + '<div class="et-chat-log" aria-live="polite"></div>'
    + '<form class="et-chat-form"><input type="text" name="q" autocomplete="off" placeholder="Es. click sul telefono, Shopify, cookie…" aria-label="Messaggio"><button class="et-chat-send" type="submit">Invia</button></form>';

  document.body.appendChild(panel);
  document.body.appendChild(btn);

  var log = panel.querySelector(".et-chat-log");
  var chips = panel.querySelector(".et-chips");
  var form = panel.querySelector("form");
  var input = form.querySelector("input");
  var history = [];
  try { history = JSON.parse(sessionStorage.getItem("et-chat") || "[]"); } catch (e) { history = []; }

  ["Click sul telefono", "E-commerce", "Cookie e consenso", "Collaborazione"].forEach(function (label) {
    var c = document.createElement("button");
    c.type = "button";
    c.className = "et-chip";
    c.textContent = label;
    c.addEventListener("click", function () { say(label); });
    chips.appendChild(c);
  });

  function bubble(role, html) {
    var el = document.createElement("div");
    el.className = "et-msg " + role;
    el.innerHTML = html;
    log.appendChild(el);
    log.scrollTop = log.scrollHeight;
  }
  function render(item) {
    if (item.role === "user") bubble("user", esc(item.text));
    else bubble("bot", item.html);
  }
  function paint(res) {
    var html = "<p>" + esc(res.text) + "</p>";
    res.cards.forEach(function (c) {
      html += '<a class="et-card" href="' + esc(c.href) + '"><b>' + esc(c.name) + '</b><i>' + esc(c.why) + '</i><em>' + esc(c.price) + ' · apri la scheda</em></a>';
    });
    if (res.links.length) {
      html += '<div class="et-links">';
      res.links.forEach(function (l) {
        html += '<a href="' + esc(l.href) + '">' + esc(l.label) + '</a>';
      });
      html += "</div>";
    }
    return html;
  }
  function say(text) {
    var clean = text.trim();
    if (!clean) return;
    history.push({ role: "user", text: clean });
    render(history[history.length - 1]);
    var res = reply(clean);
    var html = paint(res);
    history.push({ role: "bot", html: html });
    render(history[history.length - 1]);
    try { sessionStorage.setItem("et-chat", JSON.stringify(history.slice(-30))); } catch (e) {}
    input.value = "";
  }
  function setOpen(open) {
    panel.hidden = !open;
    btn.setAttribute("aria-expanded", open ? "true" : "false");
    btn.setAttribute("aria-label", open ? "Chiudi la chat" : "Apri la chat");
    if (open) {
      if (!history.length) {
        var first = reply("ciao");
        history.push({ role: "bot", html: paint(first) });
        render(history[0]);
        try { sessionStorage.setItem("et-chat", JSON.stringify(history)); } catch (e) {}
      }
      setTimeout(function () { input.focus(); }, 30);
    } else btn.focus();
  }
  history.forEach(render);
  btn.addEventListener("click", function () { setOpen(panel.hidden); });
  panel.querySelector(".et-chat-x").addEventListener("click", function () { setOpen(false); });
  form.addEventListener("submit", function (e) { e.preventDefault(); say(input.value); });
  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape" && !panel.hidden) setOpen(false);
  });
})();
